package co.com.empresa.domain.type;import co.com.empresa.commons.exception.DomainException;import co.com.empresa.domain.constants.DomainErrors;import co.com.empresa.domain.typecategory.ITypeCategoryRepository;import org.junit.jupiter.api.DisplayName;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.InjectMocks;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.data.domain.Example;import java.util.Collections;import java.util.List;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;@ExtendWith(MockitoExtension.class)class TypeDomainServiceTest {    @Mock    private ITypeRepository typeRepository;    @Mock    private ITypeCategoryRepository categoryRepository;    @InjectMocks    private TypeDomainService typeDomainService;    @Test    @DisplayName("validateUniqueness: Should not throw exception when no duplicate is found")    void validateUniqueness_NoDuplicate_Success() {        Type type = Type.builder()                .id(1L)                .typeCategoryId(10L)                .code("UNIQ01")                .build();        when(typeRepository.findAll(any(Example.class))).thenReturn(Collections.emptyList());        assertDoesNotThrow(() -> typeDomainService.validateUniqueness(type));        verify(typeRepository, times(1)).findAll(any(Example.class));    }    @Test    @DisplayName("validateUniqueness: Should throw exception when duplicate code exists for same category")    void validateUniqueness_DuplicateExists_ThrowsException() {        Type type = Type.builder()                .id(1L)                .typeCategoryId(10L)                .code("DUP01")                .build();        Type duplicate = Type.builder()                .id(2L)                .typeCategoryId(10L)                .code("DUP01")                .build();        when(typeRepository.findAll(any(Example.class))).thenReturn(List.of(duplicate));        DomainException exception = assertThrows(DomainException.class, () -> typeDomainService.validateUniqueness(type));        assertEquals(DomainErrors.ERROR_TYPE_CODE_DUPLICATE, exception.getMessage());    }    @Test    @DisplayName("validateCategoryExists: Should not throw exception when category exists")    void validateCategoryExists_Exists_Success() {        Long categoryId = 10L;        when(categoryRepository.existsById(categoryId)).thenReturn(true);        assertDoesNotThrow(() -> typeDomainService.validateCategoryExists(categoryId));    }    @Test    @DisplayName("validateCategoryExists: Should throw exception when category does not exist")    void validateCategoryExists_NotFound_ThrowsException() {        Long categoryId = 10L;        when(categoryRepository.existsById(categoryId)).thenReturn(false);        DomainException exception = assertThrows(DomainException.class, () -> typeDomainService.validateCategoryExists(categoryId));        assertEquals(DomainErrors.ERROR_TYPE_CATEGORY_NOT_FOUND, exception.getMessage());    }}